args.command:
node -e "
import('./src/pricing.js').then(async (p) => {
  const { applyCoupon } = await import('./src/coupons.js');
  const priced = p.priceLines([{ id: 'a', unitPriceCents: 250, qty: 3 }, { id: 'b', unitPriceCents: 202, qty: 5 }]);
  const perLine = priced.lines.reduce((s, l) => s + Math.floor(l.lineNet*7/100 + 0.5), 0);
  const whole = Math.floor(priced.discountedSubtotal*7/100 + 0.5);
  console.log({ discountedSubtotal: priced.discountedSubtotal, applyCoupon: applyCoupon(priced,7).couponDiscount, perLine, whole });
});
"

